    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def polygon_area(p):
    n = len(p)
    area = 0
    for i in range(n):
        j = (i + 1) % n
        area += p[i][0] * p[j][1]
        area -= p[j][0] * p[i][1]
    return abs(area) / 2.0

def find_bulkheads(C, N, vertices):
    def find_divide_point(p, target_area):
        n = len(p)
        total_area = polygon_area(p)
        if total_area <= target_area:
            return None

        for i in range(n):
            j = (i + 1) % n
            if cross(p[i], p[j], (p[i][0] + p[j][0]) / 2, (p[i][1] + p[j][1]) / 2) > 0:
                mid = ((p[i][0] + p[j][0]) / 2, (p[i][1] + p[j][1]) / 2)
                left = p[i:j+1]
                right = p[j:] + p[:i+1]
                if polygon_area(left) >= target_area:
                    return mid
                elif polygon_area(right) >= target_area:
                    return mid
        return None

    def divide_polygon(p, target_area):
        if polygon_area(p) <= target_area:
            return [p]

        divide_point = find_divide_point(p, target_area)
        if not divide_point:
            return [p]

        n = len(p)
        for i in range(n):
            if p[i] == divide_point:
                break

        left = p[i:] + p[:i+1]
        right = p[i+1:] + p[:i]

        return divide_polygon(left, target_area) + divide_polygon(right, target_area)

    sections = divide_polygon(vertices, C)
    M = len(sections)
    bulkheads = []

